import { DatabaseSync } from "node:sqlite";

export interface ChatMessage {
  id: number;
  user: string;
  text: string;
  timestamp: string;
}

const DB_PATH = "/home/user/qwik-app/chat.db";

declare global {
  // eslint-disable-next-line no-var
  var __chatDb: DatabaseSync | undefined;
  // eslint-disable-next-line no-var
  var __chatSubscribers: Set<(message: ChatMessage) => void> | undefined;
}

function createDb(): DatabaseSync {
  const db = new DatabaseSync(DB_PATH);
  db.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user TEXT NOT NULL,
      text TEXT NOT NULL,
      timestamp TEXT NOT NULL
    );
  `);
  return db;
}

/** Returns a singleton SQLite database connection, creating the table if needed. */
export function getDb(): DatabaseSync {
  if (!globalThis.__chatDb) {
    globalThis.__chatDb = createDb();
  }
  return globalThis.__chatDb;
}

/** Returns the process-wide set of active SSE subscriber callbacks. */
function getSubscribers(): Set<(message: ChatMessage) => void> {
  if (!globalThis.__chatSubscribers) {
    globalThis.__chatSubscribers = new Set();
  }
  return globalThis.__chatSubscribers;
}

export function getAllMessages(): ChatMessage[] {
  const db = getDb();
  const rows = db
    .prepare("SELECT id, user, text, timestamp FROM messages ORDER BY id ASC")
    .all();
  return rows as unknown as ChatMessage[];
}

export function insertMessage(user: string, text: string): ChatMessage {
  const db = getDb();
  const timestamp = new Date().toISOString();
  const result = db
    .prepare("INSERT INTO messages (user, text, timestamp) VALUES (?, ?, ?)")
    .run(user, text, timestamp);
  const message: ChatMessage = {
    id: Number(result.lastInsertRowid),
    user,
    text,
    timestamp,
  };
  return message;
}

/** Subscribes to newly created chat messages. Returns an unsubscribe function. */
export function subscribe(callback: (message: ChatMessage) => void): () => void {
  const subscribers = getSubscribers();
  subscribers.add(callback);
  return () => {
    subscribers.delete(callback);
  };
}

/** Broadcasts a message to all active SSE subscribers. */
export function broadcast(message: ChatMessage): void {
  const subscribers = getSubscribers();
  for (const callback of subscribers) {
    try {
      callback(message);
    } catch {
      // ignore broken subscriber
    }
  }
}

import type { RequestHandler } from "@builder.io/qwik-city";
import {
  broadcast,
  getAllMessages,
  insertMessage,
  subscribe,
  type ChatMessage,
} from "~/lib/db";

function encodeMessage(message: ChatMessage): Uint8Array {
  const payload = `data: ${JSON.stringify(message)}\n\n`;
  return new TextEncoder().encode(payload);
}

/** GET /api/messages - Establishes a persistent SSE stream of chat messages. */
export const onGet: RequestHandler = async (requestEvent) => {
  requestEvent.headers.set("Content-Type", "text/event-stream");
  requestEvent.headers.set("Cache-Control", "no-cache");
  requestEvent.headers.set("Connection", "keep-alive");

  // Prevent Qwik City / proxies from buffering or compressing the stream.
  requestEvent.headers.set("X-Accel-Buffering", "no");

  const writableStream = requestEvent.getWritableStream();
  const writer = writableStream.getWriter();

  // Immediately stream all existing messages.
  const existingMessages = getAllMessages();
  for (const message of existingMessages) {
    await writer.write(encodeMessage(message));
  }

  // Broadcast any newly posted messages to this connection.
  const unsubscribe = subscribe((message) => {
    writer.write(encodeMessage(message)).catch(() => {
      // Connection likely closed; ignore write errors.
    });
  });

  const cleanup = () => {
    unsubscribe();
    writer.close().catch(() => {
      // already closed
    });
  };

  requestEvent.signal.addEventListener("abort", cleanup);
};

/** POST /api/messages - Persists a new chat message and broadcasts it to all SSE clients. */
export const onPost: RequestHandler = async (requestEvent) => {
  let body: unknown;
  try {
    body = await requestEvent.parseBody();
  } catch {
    throw requestEvent.json(400, { error: "Invalid JSON body" });
  }

  const { user, text } = (body ?? {}) as Record<string, unknown>;

  if (
    typeof user !== "string" ||
    typeof text !== "string" ||
    user.trim().length === 0 ||
    text.trim().length === 0
  ) {
    throw requestEvent.json(400, {
      error: "Both 'user' and 'text' are required non-empty strings.",
    });
  }

  const message = insertMessage(user, text);
  broadcast(message);

  throw requestEvent.json(201, message);
};

